import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class MapConcurrencyDemo {
    private final Map<String, String> concurrentMap = new ConcurrentHashMap<>();
    private final Map<String, String> syncMap = Collections.synchronizedMap(new HashMap<>());

    public void performAtomicOperations() {
        // ConcurrentHashMap natively supports atomic compound operations
        concurrentMap.putIfAbsent("session.token", "xyz-123");

        // Collections.synchronizedMap requires manual external synchronization for compound actions
        synchronized (syncMap) {
            if (!syncMap.containsKey("session.token")) {
                syncMap.put("session.token", "xyz-123");
            }
        }
    }
}
